DROP FUNCTION public.can_post_chat(uuid,uuid); ALTER FUNCTION public.paid_post_chat(uuid,uuid) RENAME TO can_post_chat;
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND CASE WHEN _other=public.support_admin_id() OR public.has_role(auth.uid(),'admin') THEN true WHEN _post IS NULL AND public.free_work_chat(_other) THEN true WHEN NOT public.has_paid_bell(auth.uid()) THEN false WHEN _post IS NULL THEN EXISTS(SELECT 1 FROM public.bell_board_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.vehicle_demand_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.service_request_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.service_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.messages WHERE post_id IS NULL AND ((sender_id=auth.uid() AND receiver_id=_other) OR (receiver_id=auth.uid() AND sender_id=_other))) ELSE EXISTS(SELECT 1 FROM public.post_chat_pairs WHERE post_id=_post AND ((member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) END $$;
DROP FUNCTION public.guard_prime99_notice(); ALTER FUNCTION public.guard_paid_notice() RENAME TO guard_prime99_notice;
CREATE OR REPLACE FUNCTION public.guard_prime99_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE zone text; mode text:=coalesce(current_setting('app.bell_notice',true),''); BEGIN IF EXISTS(SELECT 1 FROM public.free_work_notice_queue WHERE notification_id=NEW.id AND user_id=NEW.user_id) THEN IF public.free_work_notice_allowed(NEW.user_id) THEN RETURN NEW;ELSE RETURN NULL;END IF;END IF; IF NOT public.has_paid_bell(NEW.user_id) OR EXISTS(SELECT 1 FROM public.notification_preferences WHERE user_id=NEW.user_id AND NOT enabled) THEN RETURN NULL; END IF; SELECT timezone INTO zone FROM public.notification_preferences WHERE user_id=NEW.user_id; zone:=coalesce(zone,'Asia/Kolkata'); IF NOT public.notice_window_open(now(),zone) THEN IF NOT EXISTS(SELECT 1 FROM public.deferred_listing_notices WHERE user_id=NEW.user_id AND post_id IS NOT DISTINCT FROM NEW.post_id AND matched_post_id IS NOT DISTINCT FROM NEW.matched_post_id AND message=NEW.message AND processed_at IS NULL) THEN INSERT INTO public.deferred_listing_notices(user_id,post_id,matched_post_id,message,notice_mode,available_at) VALUES(NEW.user_id,NEW.post_id,NEW.matched_post_id,NEW.message,mode,public.next_notice_open(now(),zone)); END IF; RETURN NULL; END IF; IF NOT public.can_notify(NEW.user_id) THEN RETURN NULL; END IF; RETURN NEW; END $$;